24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const basePremiumOf = (item: Item): number => {
45	  if (item.type === "amulet") return 60;
46	  return 100;
47	};
48	
49	const premiumFor = (step: QuoteStep): number => {
50	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
51	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResult => {
55	  return { results: scenario.steps.map((step) => ({ premium: premiumFor(step as QuoteStep) })) };
56	};
